// THROWAWAY: Dida-reference workspace. Synthetic data, in-memory changes only.
const compactScreen=()=>matchMedia('(max-width:900px)').matches;
const oldBind=bind,oldRender=render;
let taskQuery='',taskSort='manual',entryDraft='',undoItem=null,searchOpen=false,menuOpen=false;
const noteDrafts=new Map(),today='2026-10-18',lists=['学习','个人项目','生活'];
const icons={tasks:'<rect x="4" y="4" width="16" height="16" rx="4"/><path d="m8 12 3 3 5-6"/>',today:'<rect x="4" y="5" width="16" height="15" rx="3"/><path d="M8 3v4m8-4v4M4 10h16M9 14h6m-6 3h3"/>',inbox:'<path d="m5 5-3 10v4h20v-4L19 5ZM2 15h6l2 3h4l2-3h6"/>',week:'<rect x="4" y="5" width="16" height="15" rx="3"/><path d="M8 3v4m8-4v4M4 10h16m-12 5h8"/>',all:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',list:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 9h8m-8 4h8m-8 4h5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3c-1 .5-1 1-1 2m0 3h.01"/>',crown:'<path d="m3 6 5 5 4-7 4 7 5-5-2 13H5Zm3 10h12"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',flag:'<path d="M5 21V4m0 1c5-4 8 4 14 0v10c-6 4-9-4-14 0"/>',check:'<path d="m5 12 4 4L19 6"/>',sync:'<path d="M20 7V3m0 4h-4M4 17v4m0-4h4M5 7a8 8 0 0 1 14-1M19 17A8 8 0 0 1 5 18"/>'};
const icon=n=>`<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.list}</svg>`;
const ib=(id,n,label)=>`<button id="${id}" class="icon-button" aria-label="${label}" title="${label}">${icon(n)}</button>`;
function seedWorkspace(){tasks=structuredClone(initial).map(t=>({...t,date:today,priority:t.id===3?'高':t.id===2?'中':'无',subtasks:t.id===3?[{title:'整理竞品的关键流程',done:true},{title:'记录可复用的交互细节',done:false},{title:'补充问题与下一步',done:false}]:[]}));tasks.push({id:7,title:'预约周末的体检',list:'生活',date:'',time:'',note:'',priority:'无',done:false,subtasks:[]},{id:8,title:'复习数据库索引与事务',list:'学习',date:'2026-10-19',time:'09:00',note:'结合例题，记录还没掌握的知识点。',priority:'中',done:false,subtasks:[]});selected=compactScreen()?null:3;counter=10;filter='今天'}
seedWorkspace();
function inView(t,n=filter){return n==='已完成'?t.done:n==='全部'?!t.done:n==='今天'?!t.done&&t.date===today:n==='最近7天'?!t.done&&t.date>=today&&t.date<='2026-10-24':n==='收集箱'?!t.done&&!t.date:!t.done&&t.list===n}
function workspaceTasks(){let a=tasks.filter(t=>inView(t)&&(!taskQuery||(t.title+' '+t.note).toLowerCase().includes(taskQuery.toLowerCase())));return taskSort==='time'?a.slice().sort((a,b)=>(a.time||'99').localeCompare(b.time||'99')):a}
function closeTask(){const last=selected;selected=null;render();document.querySelector(`[data-select="${last}"]`)?.focus({preventScroll:true})}
function openTask(id){selected=id;render()}
function changed(){if(state==='offline')pending++}
function toggleTask(id){const t=tasks.find(t=>t.id===id);undoItem={id,before:t.done};t.done=!t.done;changed();if(selected===id)selected=null;render();notify(t.done?'任务已完成':'任务已重新打开',true)}
notify=function(text,canUndo=false){clearTimeout(timer);const n=document.getElementById('notice');n.innerHTML=`<span>${esc(text)}</span>${canUndo?'<button id="undo-task">撤销</button>':''}`;if(canUndo)document.getElementById('undo-task').onclick=()=>{const t=tasks.find(t=>t.id===undoItem?.id);if(t){t.done=undoItem.before;changed();render();notify('已撤销完成操作')}undoItem=null};else timer=setTimeout(()=>n.textContent='',3500)};
function taskRow(t){return `<div class="work-task ${selected===t.id?'is-selected':''} ${t.done?'is-done':''}"><button class="task-checkbox priority-${t.priority==='高'?'high':t.priority==='中'?'medium':'none'}" data-done="${t.id}" aria-label="${t.done?'重新打开':'完成'}：${esc(t.title)}" aria-pressed="${t.done}"><span>${t.done?icon('check'):''}</span></button><button class="work-task-open" data-select="${t.id}" aria-label="查看详情：${esc(t.title)}"><span class="work-task-title">${esc(t.title)}</span>${t.subtasks?.length?`<span class="subtask-count">${icon('list')}${t.subtasks.filter(s=>s.done).length}/${t.subtasks.length}</span>`:''}<span class="work-task-list">${esc(t.list)}</span><span class="work-task-time">${esc(t.time)}</span></button></div>`}
function navItem(n,ic){return `<button class="work-nav ${filter===n?'is-current':''}" data-filter="${n}" aria-pressed="${filter===n}">${icon(ic)}<span>${n}</span><small>${tasks.filter(t=>inView(t,n)).length||''}</small></button>`}
function rail(){return `<nav class="work-rail" aria-label="应用入口"><a class="rail-brand" href="?scene=home" data-scene="home" title="纸序官网"><span class="brand-icon" aria-hidden="true"></span><span class="sr-only">纸序官网</span></a><button class="rail-active icon-button" data-filter="今天" aria-label="任务">${icon('tasks')}</button>${ib('open-search','search','搜索任务')}<div class="rail-spacer"></div><a class="icon-button" href="?scene=membership" data-scene="membership" aria-label="会员">${icon('crown')}</a><a class="icon-button" href="?scene=help" data-scene="help" aria-label="帮助">${icon('help')}</a><button class="demo-toggle" id="demo-toggle" aria-expanded="${document.body.classList.contains('lab-open')}">演示</button></nav>`}
function sidebar(){return `<aside class="work-sidebar ${menuOpen?'mobile-open':''}"><div class="work-account"><strong>纸序 <span>Paperdo</span></strong>${ib('close-nav','close','关闭清单导航')}</div><nav aria-label="任务视图">${navItem('今天','today')}${navItem('最近7天','week')}${navItem('收集箱','inbox')}${navItem('全部','all')}</nav><div class="nav-divider"></div><div class="work-section-label">我的清单</div><nav class="user-lists" aria-label="我的清单">${lists.map((n,i)=>`<button class="work-nav ${filter===n?'is-current':''}" data-filter="${n}" aria-pressed="${filter===n}"><span class="list-color color-${i}">${icon('list')}</span><span>${n}</span><small>${tasks.filter(t=>inView(t,n)).length||''}</small></button>`).join('')}</nav><div class="nav-divider"></div>${navItem('已完成','tasks')}<div class="sidebar-bottom"><a href="?scene=membership" data-scene="membership">${icon('crown')}高级会员${icon('chevron')}</a><span class="local-status">${icon('sync')}${state==='offline'?`离线 · ${pending} 项待同步`:'本地演示'}</span></div></aside>`}
function dateLabel(t){return !t.date?'设置日期':(t.date===today?'今天':t.date==='2026-10-19'?'明天':t.date.slice(5).replace('-','月')+'日')+(t.time?'，'+t.time:'')}
detail=function(){const t=tasks.find(t=>t.id===selected);if(!t||['loading','error'].includes(state))return '';const tag=compactScreen()?'dialog':'aside';return `<${tag} id="task-detail" class="work-detail" aria-labelledby="detail-title"><div class="detail-bar"><button class="date-trigger" id="date-trigger" aria-expanded="false">${icon('today')}<span>${dateLabel(t)}</span></button><label class="priority-picker" title="优先级">${icon('flag')}<select id="detail-priority" aria-label="优先级">${['无','低','中','高'].map(n=>`<option ${t.priority===n?'selected':''}>${n}</option>`).join('')}</select></label>${ib('close-detail','close','关闭任务详情')}</div><form id="date-form" class="date-popover" hidden><label>日期<input type="date" id="task-date" value="${t.date}"></label><label>时间<input type="time" id="task-time" value="${t.time}"></label><button type="button" id="clear-date">清除日期</button><button class="primary" type="submit">确定</button></form><div class="detail-scroll"><div class="detail-title-row"><button class="task-checkbox" data-done="${t.id}" aria-label="${t.done?'重新打开':'完成'}详情任务"><span>${t.done?icon('check'):''}</span></button><h2 id="detail-title"><input id="task-title" aria-label="任务名称" value="${esc(t.title)}" maxlength="160"></h2></div><form id="note-form"><label class="sr-only" for="task-note">任务备注</label><textarea id="task-note" placeholder="添加描述…" maxlength="2000">${esc(noteDrafts.get(t.id)??t.note)}</textarea><div class="note-save"><span id="draft-state">${noteDrafts.has(t.id)?'未保存':'已保存到本次演示'}</span><button type="submit" id="save-note">保存</button></div></form><div class="subtasks">${(t.subtasks||[]).map((s,i)=>`<label class="subtask ${s.done?'is-done':''}"><input type="checkbox" data-subtask="${i}" ${s.done?'checked':''}><span>${esc(s.title)}</span></label>`).join('')}<form id="subtask-form">${icon('plus')}<input id="new-subtask" aria-label="添加检查项" placeholder="添加检查项" maxlength="120"></form></div></div><footer class="detail-footer"><label>${icon('inbox')}<select id="task-list" aria-label="所属清单">${lists.map(n=>`<option ${n===t.list?'selected':''}>${n}</option>`).join('')}</select></label><span>${state==='offline'?'离线编辑':'本次页面内保存'}</span></footer></${tag}>`};
app=function(){const arr=workspaceTasks(),done=tasks.filter(t=>t.done&&t.date===today).length;let content='';if(state==='loading')content='<div class="work-state" aria-busy="true"><h2>正在加载任务…</h2><button data-state="normal">结束演示</button></div>';else if(state==='error')content='<div class="work-state"><h2>暂时无法读取任务</h2><p>请检查网络后重试。</p><button data-state="normal" class="primary">重新加载</button></div>';else content=`${state==='offline'?`<div class="work-offline">离线可继续编辑 · ${pending} 项变更待同步<button data-state="normal">模拟恢复</button></div>`:''}<form id="add-form" class="work-entry">${icon('plus')}<input id="new-task" aria-label="添加任务" value="${esc(entryDraft)}" placeholder="添加任务" autocomplete="off" maxlength="160" required><button type="submit" aria-label="添加任务到清单">↵</button></form>${searchOpen?`<div class="work-search">${icon('search')}<input id="task-search" aria-label="搜索任务" placeholder="搜索任务或备注" value="${esc(taskQuery)}">${ib('close-search','close','关闭搜索')}</div>`:''}<div class="work-group"><span>${icon('down')}${taskQuery?'搜索结果':esc(filter==='已完成'?'已完成':'待办任务')}<small>${arr.length}</small></span><span class="group-date">${filter==='今天'?'10月18日，星期日':''}</span></div><section id="task-rows" aria-label="任务列表">${arr.length?arr.map(taskRow).join(''):`<div class="work-state">${icon('tasks')}<h2>${taskQuery?'没有找到相关任务':filter==='已完成'?'还没有已完成的任务':'没有待办任务'}</h2><p>${taskQuery?'试试其他关键词。':'把想做的事情记录在这里。'}</p></div>`}</section>${filter==='今天'&&done&&!taskQuery?`<details class="completed-group"><summary>已完成 <span>${done}</span></summary>${tasks.filter(t=>t.done&&t.date===today).map(taskRow).join('')}</details>`:''}`;return `<div class="work-app ${selected!==null?'with-detail':''}">${rail()}${sidebar()}${menuOpen?'<button class="nav-backdrop" id="nav-backdrop" aria-label="关闭清单导航"></button>':''}<main id="main" class="work-main" tabindex="-1"><header class="work-heading">${ib('toggle-nav','menu','展开清单导航')}<h1>${esc(filter)}</h1><label class="work-sort"><span class="sr-only">任务排序</span><select id="task-sort"><option value="manual" ${taskSort==='manual'?'selected':''}>默认排序</option><option value="time" ${taskSort==='time'?'selected':''}>按时间排序</option></select></label>${ib('heading-search','search','搜索当前清单')}</header><div class="work-body">${content}</div><div class="work-bottom"><span>${arr.length} 项${taskQuery?'匹配任务':'任务'}</span><span><kbd>N</kbd> 添加 <kbd>/</kbd> 搜索</span></div></main>${detail()}</div>`};
function saveNote(){const t=tasks.find(t=>t.id===selected),input=document.getElementById('task-note');if(!t||!input)return;if(t.note!==input.value){t.note=input.value;changed()}noteDrafts.delete(t.id);document.getElementById('draft-state').textContent='已保存到本次演示';document.getElementById('save-note').classList.remove('unsaved')}
function bindApp(){
 document.querySelectorAll('[data-scene]').forEach(el=>el.onclick=e=>{if(e.ctrlKey||e.metaKey)return;e.preventDefault();navigate(el.dataset.scene)});
 document.querySelectorAll('[data-state]').forEach(el=>el.onclick=()=>applyState(el.dataset.state));
 document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;taskQuery='';selected=null;menuOpen=false;render()});
 document.querySelectorAll('[data-select]').forEach(el=>el.onclick=()=>openTask(Number(el.dataset.select)));
 document.querySelectorAll('[data-done]').forEach(el=>el.onclick=()=>toggleTask(Number(el.dataset.done)));
 document.getElementById('close-detail')?.addEventListener('click',closeTask);
 document.getElementById('toggle-nav').onclick=()=>{menuOpen=!menuOpen;render()};
 for(const id of ['close-nav','nav-backdrop'])document.getElementById(id)?.addEventListener('click',()=>{menuOpen=false;render()});
 document.getElementById('demo-toggle').onclick=()=>{document.body.classList.toggle('lab-open');document.getElementById('demo-toggle').setAttribute('aria-expanded',document.body.classList.contains('lab-open'))};
 for(const id of ['open-search','heading-search'])document.getElementById(id).onclick=()=>{searchOpen=true;render();document.getElementById('task-search')?.focus()};
 document.getElementById('close-search')?.addEventListener('click',()=>{searchOpen=false;taskQuery='';render()});
 const add=document.getElementById('add-form');if(add){const input=document.getElementById('new-task');input.oninput=()=>entryDraft=input.value;add.onsubmit=e=>{e.preventDefault();const title=input.value.trim();if(!title)return;tasks.unshift({id:counter++,title,list:lists.includes(filter)?filter:'生活',date:filter==='收集箱'?'':today,time:'',note:'',done:false,priority:'无',subtasks:[]});changed();if(state==='empty')state='normal';if(filter==='已完成')filter='今天';entryDraft='';taskQuery='';render();document.getElementById('new-task').focus();notify('任务已添加')}}
 const search=document.getElementById('task-search');if(search){const update=()=>{taskQuery=search.value;render();document.getElementById('task-search').focus()};search.oninput=e=>{if(!e.isComposing)update()};search.oncompositionend=update}
 document.getElementById('task-sort').onchange=e=>{taskSort=e.target.value;render()};
 const title=document.getElementById('task-title');if(title)title.oninput=()=>{const t=tasks.find(t=>t.id===selected);if(title.value.trim()&&t.title!==title.value.trim()){t.title=title.value.trim();changed();const row=document.querySelector(`[data-select="${t.id}"]`);if(row){row.querySelector('.work-task-title').textContent=t.title;row.setAttribute('aria-label','查看详情：'+t.title)}document.querySelector(`#task-rows [data-done="${t.id}"]`)?.setAttribute('aria-label',(t.done?'重新打开：':'完成：')+t.title)}};
 const note=document.getElementById('task-note');if(note){note.oninput=()=>{noteDrafts.set(selected,note.value);document.getElementById('draft-state').textContent='未保存';document.getElementById('save-note').classList.add('unsaved')};note.onblur=saveNote;document.getElementById('note-form').onsubmit=e=>{e.preventDefault();saveNote();notify('备注已保存')}}
 document.getElementById('detail-priority')?.addEventListener('change',e=>{tasks.find(t=>t.id===selected).priority=e.target.value;changed();render()});
 document.getElementById('task-list')?.addEventListener('change',e=>{tasks.find(t=>t.id===selected).list=e.target.value;changed();render()});
 document.getElementById('date-trigger')?.addEventListener('click',()=>{const f=document.getElementById('date-form');f.hidden=!f.hidden;document.getElementById('date-trigger').setAttribute('aria-expanded',!f.hidden)});
 document.getElementById('date-form')?.addEventListener('submit',e=>{e.preventDefault();const t=tasks.find(t=>t.id===selected);t.date=document.getElementById('task-date').value;t.time=t.date?document.getElementById('task-time').value:'';changed();render()});
 document.getElementById('clear-date')?.addEventListener('click',()=>{const t=tasks.find(t=>t.id===selected);t.date='';t.time='';changed();render()});
 document.querySelectorAll('[data-subtask]').forEach(el=>el.onchange=()=>{tasks.find(t=>t.id===selected).subtasks[Number(el.dataset.subtask)].done=el.checked;changed();render()});
 document.getElementById('subtask-form')?.addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('new-subtask');if(!input.value.trim())return;tasks.find(t=>t.id===selected).subtasks.push({title:input.value.trim(),done:false});changed();render();document.getElementById('new-subtask').focus()});
 const modal=document.querySelector('dialog#task-detail');if(modal){modal.showModal();modal.oncancel=e=>{e.preventDefault();closeTask()}}
}
 bind=function(){if(scene==='app')bindApp();else oldBind()};
 render=function(){document.body.dataset.page=scene;oldRender()};
 document.getElementById('reset').onclick=()=>{seedWorkspace();state='normal';pending=0;taskQuery='';entryDraft='';searchOpen=false;noteDrafts.clear();render();notify('示例已重置')};
 document.addEventListener('keydown',e=>{if(e.isComposing||e.altKey||e.ctrlKey||e.metaKey||scene!=='app')return;if(e.key==='Escape'){if(selected!==null){e.preventDefault();closeTask()}else if(searchOpen){searchOpen=false;taskQuery='';render()}return}if(e.target.closest('input,textarea,select,[contenteditable]'))return;if(e.key.toLowerCase()==='n'){e.preventDefault();document.getElementById('new-task')?.focus()}if(e.key==='/'){e.preventDefault();searchOpen=true;render();document.getElementById('task-search')?.focus()}});
 matchMedia('(max-width:900px)').addEventListener('change',()=>{if(scene==='app')render()});
 render();
